    "A property appears to be used symmetrically in the data (whenever A→B exists, B→A also exists) but is not declared owl:SymmetricProperty. Declaring it symmetric allows reasoners to infer the reverse direction automatically.": "데이터에서 속성이 대칭적으로 사용되고 있는 것으로 보입니다(A→B가 존재할 때마다 B→A도 존재). 그러나 owl:SymmetricProperty로 선언되어 있지 않습니다. 대칭 속성으로 선언하면 추론기가 역방향을 자동으로 추론할 수 있습니다.",
    "A property has exactly one direct sub-property. Mirrors P2.2 for properties: if a property hierarchy node has only one child, it may be a superfluous intermediate that adds no modelling value.": "속성이 정확히 하나의 직접 하위 속성만 가지고 있습니다. 이는 속성에 대한 P2.2와 동일한 패턴입니다. 속성 계층 구조의 노드에 자식이 하나뿐이라면, 모델링상 가치를 더하지 못하는 불필요한 중간 노드일 수 있습니다.",
    "A property name encodes its range type (e.g., 'hasPersonName', 'containsEvent'). Embedding the range in the label couples naming to structure: renaming or changing the range requires renaming the property, and it conflates two distinct modelling concerns.": "속성 이름에 범위 타입이 그대로 포함되어 있습니다(예: 'hasPersonName', 'containsEvent'). 레이블에 범위를 포함시키면 이름이 구조와 결합되어, 범위를 변경하거나 이름을 바꿀 때 속성 이름도 함께 변경해야 하며, 서로 다른 두 가지 모델링 관심사가 혼재됩니다.",
    "A property shows transitive usage patterns (A→B, B→C implies A→C) but is not declared owl:TransitiveProperty. Adding the declaration lets reasoners close the transitive chain automatically.": "속성이 전이적 사용 패턴을 보이고 있습니다(A→B, B→C이면 A→C가 성립). 그러나 owl:TransitiveProperty로 선언되어 있지 않습니다. 이 선언을 추가하면 추론기가 전이적 연쇄를 자동으로 완성할 수 있습니다.",
    "A running SQL Warehouse": "실행 중인 SQL 웨어하우스",
