    "Already running on a Volume-only registry? Use": "이미 볼륨 전용 레지스트리에서 실행 중이신가요? 다음을 사용하세요",
    "Always equals the Postgres graph schema — Lakebase places the": "항상 Postgres 그래프 스키마와 동일합니다 — Lakebase는 다음을 배치합니다",
    "Always exposed (they run before a domain is selected, so no per-domain policy can hide them):": "항상 노출됩니다 (도메인이 선택되기 전에 실행되므로, 도메인별 정책으로 숨길 수 없습니다):",
    "An Admin (": "관리자 (",
    "An entity has exactly one direct subclass. This is often a sign of unnecessary intermediate nodes: if a parent has only one child, the hierarchy could usually be flattened without loss of semantics, unless the parent is used in axioms independently.": "엔티티가 정확히 하나의 직접 하위 클래스만 가지고 있습니다. 이는 불필요한 중간 노드의 징후인 경우가 많습니다. 상위 엔티티가 논리 규칙에서 독립적으로 사용되지 않는다면, 자식이 하나뿐인 경우 의미 손실 없이 계층 구조를 단순화할 수 있습니다.",
    "An entity is declared disjoint from one of its own subclasses. This is a contradiction: no individual can simultaneously belong to both an entity and its subclass if they are disjoint, making the subclass unsatisfiable (always empty).": "엔티티가 자신의 하위 클래스 중 하나와 서로 배타적으로 선언되었습니다. 이는 논리적 모순입니다. 엔티티와 그 하위 클래스가 서로 배타적이라면 어떤 개체도 두 클래스에 동시에 속할 수 없으며, 이로 인해 해당 하위 클래스는 충족 불가능(항상 공집합)해집니다.",
    "An entity is explicitly declared as a direct subclass of both a parent entity and one of that parent's ancestors. The declaration to the ancestor is redundant because subclass transitivity already implies it, and it can mislead reasoners.": "엔티티가 상위 엔티티와 그 상위 엔티티의 조상 엔티티 모두에 대해 직접적인 하위 클래스로 명시적으로 선언되었습니다. 하위 클래스의 전이성에 의해 조상에 대한 선언은 이미 암시되므로 중복이며, 추론기에 혼란을 줄 수 있습니다.",
    "An object property or datatype property has no rdfs:domain or rdfs:range declaration. Without these constraints, reasoners cannot infer the types of subjects or objects, reducing the expressiveness and validation power of the ontology.": "object property 또는 datatype property에 rdfs:domain 또는 rdfs:range 선언이 없습니다. 이러한 제약이 없으면 추론기가 주어나 목적어의 타입을 추론할 수 없어, 온톨로지의 표현력과 검증 능력이 저하됩니다.",
    "An ontology is a formal description of the concepts (classes/entities), their properties (attributes), and the relationships between them in a domain. OntoBricks expresses ontologies in the W3C": "온톨로지는 도메인 내의 개념(클래스/엔티티), 그 속성(속성), 그리고 그들 간의 관계에 대한 형식적인 설명입니다. OntoBricks는 온톨로지를 W3C",
