    "Axiom": "논리 규칙",
    "Axioms": "논리 규칙",
    "Axioms in the ontology produce unsatisfiable entities — e.g., an entity is simultaneously defined as a subclass of two disjoint entities, or a restriction forces contradictory types. An OWL reasoner would flag these entities as equivalent to owl:Nothing.": "온톨로지 내의 논리 규칙으로 인해 충족 불가능한 엔티티가 발생합니다. 예를 들어, 엔티티가 서로 배타적인 두 엔티티의 하위 클래스로 동시에 정의되거나, 제약 조건이 상충되는 타입을 강제하는 경우입니다. OWL 추론기는 이러한 엔티티를 owl:Nothing과 동등한 것으로 표시합니다.",
