    "Check tables to target them with \"Update from UC\" (refresh columns) or \"Remove Selected Tables\". If no tables are checked, \"Update from UC\" refreshes all loaded tables. Click on a table name to view/edit column details. Click on \"Data Source\" to change catalog.schema per table. Use \"Update Mappings\" to push catalog.schema into entity/relationship mappings.": "테이블을 체크하여 \"Update from UC\"(열 새로 고침) 또는 \"Remove Selected Tables\"의 대상으로 지정하세요. 테이블을 체크하지 않으면 \"Update from UC\"가 로드된 모든 테이블을 새로 고칩니다. 테이블 이름을 클릭하면 열 세부 정보를 보고 편집할 수 있습니다. \"Data Source\"를 클릭하면 테이블별 catalog.schema를 변경할 수 있습니다. \"Update Mappings\"를 사용하여 catalog.schema를 엔티티/관계 매핑에 반영하세요.",
