    "Check the progress of a previously started data quality check. Returns the current status, progress percentage, and per-shape results once completed.": "이전에 시작된 데이터 품질 검사의 진행 상태를 확인합니다. 완료되면 현재 상태, 진행률(%), 셰이프별 결과를 반환합니다.",
