    "Example guidelines: - Create an ontology for a customer relationship management (CRM) domain - Use CamelCase for entity names (e.g., Customer, SalesOrder, Product) - Include relationships like 'hasOrder', 'belongsTo', 'contains' - Consider that customers can have multiple orders - Products belong to categories - Include properties for common attributes like name, date, status - Focus on the main business entities and their core relationships": "예시 가이드라인: - 고객 관계 관리(CRM) 도메인을 위한 온톨로지를 만듭니다 - 엔티티 이름에 CamelCase를 사용합니다 (예: Customer, SalesOrder, Product) - 'hasOrder', 'belongsTo', 'contains'와 같은 관계를 포함합니다 - 고객이 여러 주문을 가질 수 있음을 고려합니다 - 제품은 카테고리에 속합니다 - name, date, status와 같은 공통 속성을 포함합니다 - 주요 비즈니스 엔티티와 그 핵심 관계에 집중합니다",
