    "On macOS use": "macOS에서는 다음을 사용하세요",
    "One Of (Enumeration)": "열거형 중 하나",
    "One or more entities are never used as domain, range, or type in any property assertion or restriction. Such orphan entities add vocabulary without contributing to the ontology's modelling or reasoning.": "하나 이상의 엔티티가 어떤 속성 단언이나 제약 조건에서도 도메인, 범위, 또는 타입으로 사용되지 않습니다. 이러한 고립된 엔티티는 온톨로지의 모델링이나 추론에 기여하지 않으면서 어휘만 추가합니다.",
    "One or more entities or properties have no rdfs:label. Labels are essential for human-readable documentation, UI display, and tool interoperability. Every named entity in a published ontology should carry at least one label.": "하나 이상의 엔티티 또는 속성에 rdfs:label이 없습니다. 레이블은 사람이 읽을 수 있는 문서화, UI 표시, 도구 간 상호운용성에 필수적입니다. 공개된 온톨로지의 모든 명명된 엔티티는 최소한 하나의 레이블을 가져야 합니다.",
    "Only administrators can edit team memberships.": "관리자만 팀 구성원을 편집할 수 있습니다.",
    "Only builders and admins can build a graph viewer": "빌더와 관리자만 그래프 뷰어를 빌드할 수 있습니다",
    "Only scopes your identity can read appear here. Missing one? Grant access:": "회원님의 아이디로 읽을 수 있는 범위만 여기에 표시됩니다. 누락된 항목이 있나요? 액세스 권한을 부여하세요:",
    "OntoBricks agents (OWL generation, auto-mapping, icon mapping) use this endpoint to interact with a Foundation Model. The endpoint must be a Databricks Model Serving endpoint accessible from this workspace.": "OntoBricks 에이전트(OWL 생성, 자동 매핑, 아이콘 매핑)는 이 엔드포인트를 사용해 Foundation Model과 상호작용합니다. 엔드포인트는 이 워크스페이스에서 접근 가능한 Databricks Model Serving 엔드포인트여야 합니다.",
    "OntoBricks always materializes a": "OntoBricks는 항상 다음을 구체화합니다",
    "OntoBricks can generate an end-to-end graph viewer from your Databricks tables using LLM-powered automation. Here is the fastest path from zero to a queryable graph.": "OntoBricks는 LLM 기반 자동화를 사용하여 Databricks 테이블로부터 엔드투엔드 그래프 뷰어를 생성할 수 있습니다. 쿼리 가능한 그래프까지 가장 빠르게 도달하는 경로는 다음과 같습니다.",
    "OntoBricks documentation": "OntoBricks 문서",
    "OntoBricks has just been deployed and its service principal is not yet allowed to read its own permissions.": "OntoBricks가 방금 배포되었으며 해당 서비스 주체는 아직 자체 권한을 읽을 수 없습니다.",
    "OntoBricks transforms Databricks tables into a materialized graph viewer. Design ontologies (OWL/RDFS/SHACL), map them to Unity Catalog tables via R2RML, materialize triples into a Delta-backed triple store with a Lakebase Postgres graph engine, reason over the graph, and query it through an auto-generated GraphQL API — all from a single web application running as a Databricks App.": "OntoBricks는 Databricks 테이블을 구체화된 그래프 뷰어로 변환합니다. 온톨로지(OWL/RDFS/SHACL)를 설계하고, R2RML을 통해 Unity Catalog 테이블에 매핑하고, Lakebase Postgres 그래프 엔진이 포함된 Delta 기반 트리플 스토어에 트리플을 구체화하고, 그래프에 대해 추론하며, 자동 생성된 GraphQL API를 통해 쿼리할 수 있습니다 — 모두 Databricks App으로 실행되는 단일 웹 애플리케이션에서 가능합니다.",
