    "Opens the interactive GraphiQL IDE for the selected domain. The schema is auto-generated from the ontology — every entity becomes a GraphQL type, every data property a field, and every object property a relationship.": "선택한 도메인을 위한 대화형 GraphiQL IDE를 엽니다. 스키마는 온톨로지로부터 자동 생성됩니다 — 모든 엔티티는 GraphQL 타입이 되고, 모든 데이터 속성은 필드가 되며, 모든 객체 속성은 관계가 됩니다.",
