    "Requires the Databricks bundle to have been deployed, so that the job exists, and the domain to have been built at least once. The job reads the mapped-triples snapshot every Build materialises, so it works the same on the Delta engine, on Lakebase in either mode, and on Neo4j. When a prerequisite is missing the Analytics page says which one rather than falling back to a different calculation. Runs take minutes rather than seconds.": "작업이 존재하려면 Databricks 번들이 배포되어 있어야 하고, 도메인이 최소 한 번 빌드되어 있어야 합니다. 이 작업은 빌드할 때마다 구체화되는 매핑된 트리플 스냅샷을 읽으므로 Delta 엔진, 두 모드의 Lakebase, Neo4j에서 동일하게 동작합니다. 필수 조건이 누락된 경우 다른 계산으로 대체하지 않고 Analytics 페이지에서 어떤 조건이 누락되었는지 알려줍니다. 실행에는 몇 초가 아니라 몇 분이 걸립니다.",
    "Reset": "초기화",
    "Reset Layout": "레이아웃 초기화",
    "Reset Layout (Auto-arrange)": "레이아웃 초기화(자동 배치)",
    "Reset Ontology": "온톨로지 초기화",
    "Reset View": "뷰 초기화",
    "Reset icon": "초기화 아이콘",
    "Reset layout": "레이아웃 초기화",
    "Reset view": "뷰 초기화",
    "Resolution": "해상도",
    "Resolution:": "해상도:",
    "Resolved": "해결됨",
    "Resources": "리소스",
    "Restore factory UI defaults": "출고 시 UI 기본값으로 복원",
    "Restrict the search to a single entity type (All searches every type)": "검색을 단일 엔티티 유형으로 제한합니다(전체는 모든 유형을 검색합니다)",
    "Restricts the analysis to one entity type. Centrality is then computed on that subgraph, so scores are not comparable with a full-graph run.": "분석을 하나의 엔티티 유형으로 제한합니다. 중심성은 해당 하위 그래프에서 계산되므로 점수는 전체 그래프 실행과 비교할 수 없습니다.",
    "Result Entity": "결과 엔티티",
    "Result is in [{n}, {n}]: {n}.{n} means every pair of neighbours is also connected to each other": "결과는 [{n}, {n}] 범위입니다: {n}.{n}은 모든 이웃 쌍이 서로 연결되어 있음을 의미합니다",
    "Result is in [{n}, {n}]: {n}.{n} means the node is connected to every other node": "결과는 [{n}, {n}] 범위입니다: {n}.{n}은 노드가 다른 모든 노드와 연결되어 있음을 의미합니다",
    "Result is normalised to [{n}, {n}] by dividing by": "결과는 다음으로 나누어 [{n}, {n}]로 정규화됩니다",
    "Results": "결과",
    "Resume editing": "편집 재개",
    "Retrieve triples": "트리플 조회",
    "Retry": "재시도",
    "Return cached inference results from the last completed inference run. Includes inferred triple counts, constraint violation counts, and detailed per-phase statistics.": "마지막으로 완료된 추론 실행의 캐시된 추론 결과를 반환합니다. 추론된 트리플 수, 제약 조건 위반 수 및 단계별 세부 통계를 포함합니다.",
    "Return the full payload of a single saved cohort rule. Returns": "저장된 세그먼트 규칙 하나의 전체 페이로드를 반환합니다. 반환값",
    "Returns PUBLISHED, API-exposed domains with a populated ontology and materialized graph — the prerequisites for auto-generating and executing a GraphQL schema.": "온톨로지가 채워지고 그래프가 구체화된 PUBLISHED 상태의 API 노출 도메인을 반환합니다. 이는 GraphQL 스키마를 자동 생성하고 실행하기 위한 필수 조건입니다.",
    "Returns PUBLISHED, API-exposed domains with their configured": "구성된 PUBLISHED 상태의 API 노출 도메인을 반환합니다",
    "Returns all versions available for a given domain in the registry, sorted from latest to oldest.": "레지스트리에서 지정된 도메인에 사용 가능한 모든 버전을 최신순으로 정렬하여 반환합니다.",
    "Returns every saved cohort rule on the active domain. Each entry includes the full rule payload (links, compatibility, output config) so callers can re-run, preview, or materialise without a second round-trip.": "활성 도메인의 저장된 모든 세그먼트 규칙을 반환합니다. 각 항목에는 전체 규칙 페이로드(링크, 호환성, 출력 구성)가 포함되어 있어 추가 왕복 없이 다시 실행, 미리 보기 또는 구체화할 수 있습니다.",
    "Returns the Spark SQL query generated from the domain's R2RML mappings. This is the SQL that produces": "도메인의 R2RML 매핑에서 생성된 Spark SQL 쿼리를 반환합니다. 이는 다음을 생성하는 SQL입니다",
    "Returns the auto-generated GraphQL schema in SDL (Schema Definition Language) format. The schema reflects the domain's ontology: each entity is a type, each data property a field, and each object property a typed relationship.": "SDL(Schema Definition Language) 형식의 자동 생성된 GraphQL 스키마를 반환합니다. 이 스키마는 도메인의 온톨로지를 반영합니다. 각 엔티티는 타입이 되고, 각 데이터 속성은 필드가 되며, 각 객체 속성은 유형화된 관계가 됩니다.",
    "Returns the domain's R2RML mapping document in Turtle format. R2RML defines how relational tables map to RDF triples — each TriplesMap specifies a source table, subject template, and predicate-object mappings.": "도메인의 R2RML 매핑 문서를 Turtle 형식으로 반환합니다. R2RML은 관계형 테이블이 RDF 트리플로 매핑되는 방식을 정의합니다. 각 TriplesMap은 소스 테이블, 주어 템플릿, 술어-목적어 매핑을 지정합니다.",
    "Returns the domain's ontology serialized as OWL in Turtle format. Includes the full OWL document, base URI, and class/property counts.": "도메인의 온톨로지를 Turtle 형식의 OWL로 직렬화하여 반환합니다. 전체 OWL 문서, 기본 URI, 클래스/속성 수를 포함합니다.",
    "Returns the readiness status of the domain's": "도메인의 준비 상태를 반환합니다",
    "Returns the registry location (catalog, schema, volume) for the domain. Reads from the current session if available, otherwise from environment variables. Used by external clients (e.g. MCP server) for registry discovery.": "도메인의 레지스트리 위치(카탈로그, 스키마, 볼륨)를 반환합니다. 가능한 경우 현재 세션에서 읽고, 그렇지 않으면 환경 변수에서 읽습니다. 외부 클라이언트(예: MCP 서버)가 레지스트리를 검색하는 데 사용됩니다.",
    "Returns whether the triple store is configured, which backend is active, whether the table exists and contains data, and its row count.": "트리플 스토어가 구성되었는지, 어떤 백엔드가 활성화되었는지, 테이블이 존재하고 데이터를 포함하는지, 행 수를 반환합니다.",
    "Reverse direction": "방향 반전",
    "Review Auto-generated Business Rules": "자동 생성된 비즈니스 규칙 검토",
