    "Review and sign off this version before it goes live. Run consistency checks, collect reviewer approvals, then publish. Every decision is recorded in the audit trail.": "실행 전에 이 버전을 검토하고 승인하세요. 일관성 검사를 실행하고 검토자 승인을 수집한 후 게시하세요. 모든 결정은 감사 기록에 저장됩니다.",
