    "Rules are compiled to SQL and run against this view, which holds the triples mapped from your source tables. Triples produced by reasoning are not checked.": "규칙은 SQL로 컴파일되어 소스 테이블에서 매핑된 트리플을 담고 있는 이 뷰에 대해 실행됩니다. 추론으로 생성된 트리플은 검사되지 않습니다.",
