    "Trigger an asynchronous build that generates all triples from the current ontology and mapping configuration and writes them to the configured triple store. Returns a": "현재 온톨로지와 매핑 구성에서 모든 트리플을 생성하여 설정된 트리플 스토어에 작성하는 비동기 빌드를 트리거합니다. 반환값:",
    "Triggered — refresh when you trigger": "트리거됨 — 트리거할 때 새로 고침하세요",
