    "Triple Pattern": "트리플 패턴",
    "Triple Store": "트리플 스토어",
    "Triple store is empty — run Sync first": "트리플 스토어가 비어 있습니다 — 먼저 동기화를 실행하세요",
    "Triple store status": "트리플 스토어 상태",
    "Triple store status and build execution": "트리플 스토어 상태 및 빌드 실행",
    "Triple store synchronized successfully!": "트리플 스토어가 성공적으로 동기화되었습니다!",
    "Triple store table not configured. Please set it in Domain Settings.": "트리플 스토어 테이블이 설정되지 않았습니다. 도메인 설정에서 설정하세요.",
    "Triple-Store Gateway": "트리플 스토어 게이트웨이",
    "Triple-Store Gateway:": "트리플 스토어 게이트웨이:",
    "Triples": "트리플",
    "Troubleshooting": "문제 해결",
    "Try different keywords, or browse the sections on the left.": "다른 키워드를 시도하거나 왼쪽의 섹션을 둘러보세요.",
    "Try it": "사용해 보기",
    "Two entities are declared disjoint when one is already a subclass of the other, or when disjointness is already implied by the hierarchy. The explicit disjointness assertion is redundant and may create unintended logical side-effects.": "한 엔티티가 이미 다른 엔티티의 하위 클래스이거나, 계층 구조에 의해 서로 배타성이 이미 암시되는 경우에도 두 엔티티가 서로 배타적으로 선언되었습니다. 이러한 명시적 배타성 선언은 중복이며, 의도하지 않은 논리적 부작용을 일으킬 수 있습니다.",
    "Two members are": "두 멤버가",
    "Two members are linked when they reach the same instance of this entity": "두 멤버가 이 엔티티의 동일한 인스턴스에 도달하면 연결됩니다",
    "Two or more entities or properties carry labels that are semantically similar or synonymous (detected via sentence-embedding cosine similarity). These may be duplicates or candidates for merging, equivalence declarations, or at least a clarifying note.": "두 개 이상의 엔티티 또는 속성이 의미적으로 유사하거나 동의어인 레이블을 가지고 있습니다(문장 임베딩 코사인 유사도를 통해 감지됨). 이들은 중복이거나, 병합, 동등 관계 선언, 또는 최소한 명확화를 위한 설명이 필요한 후보일 수 있습니다.",
    "Two or more entity names are so similar that a subclass relationship may exist but is not declared. This check flags candidate pairs for human review to determine whether a missing rdfs:subClassOf should be added.": "두 개 이상의 엔티티 이름이 매우 유사하여 하위 클래스 관계가 존재할 가능성이 있지만 선언되어 있지 않습니다. 이 검사는 누락된 rdfs:subClassOf 관계를 추가해야 하는지 검토할 필요가 있는 후보 쌍을 표시합니다.",
    "Two or more properties have names so similar that one may be a specialisation of the other, yet no rdfs:subPropertyOf link is declared between them. This check flags candidate pairs worth reviewing for a missing sub-property relationship.": "두 개 이상의 속성이 이름이 매우 유사하여 하나가 다른 하나의 특수화일 가능성이 있지만, 이들 간에 rdfs:subPropertyOf 관계가 선언되어 있지 않습니다. 이 검사는 누락된 하위 속성 관계를 검토할 필요가 있는 후보 쌍을 표시합니다.",
    "Two properties appear to be mutual inverses in usage (A prop1 B and B prop2 A), but owl:inverseOf is not declared between them. Declaring the inverse relationship enables reasoners to infer one direction from the other.": "두 속성이 사용상 서로의 역관계로 보입니다(A prop1 B 및 B prop2 A). 그러나 이들 사이에 owl:inverseOf가 선언되어 있지 않습니다. 역관계를 선언하면 추론기가 한 방향에서 다른 방향을 추론할 수 있습니다.",
    "Two-phase search, configurable depth, cross-domain bridges, cluster detection (client-side Graphology / server-side NetworkX), color-by-cluster, super-nodes.": "2단계 검색, 설정 가능한 깊이, 도메인 간 브리지, 클러스터 탐지(클라이언트 측 Graphology / 서버 측 NetworkX), 클러스터별 색상, 슈퍼 노드.",
    "Type": "유형",
    "Type Assertions": "유형 선언",
    "Type a value…": "값을 입력하세요…",
    "Type changed": "유형이 변경됨",
