    "UC catalog (sync registration)": "UC 카탈로그(동기화 등록)",
    "UC catalog for synced table registration. If empty: Registry catalog, then domain Delta.": "동기화된 테이블 등록을 위한 UC 카탈로그입니다. 비어 있으면 레지스트리 카탈로그, 그다음 도메인 Delta를 사용합니다.",
