    "Unity Catalog (metadata & Delta triples)": "Unity Catalog(메타데이터 및 Delta 트리플)",
    "Unity Catalog Delta tables for the triple store — no separate graph database to provision": "트리플 스토어용 Unity Catalog Delta 테이블 — 별도의 그래프 데이터베이스 프로비저닝 불필요",
