    "— drag & drop entities, relationships, inheritance arrows on the OntoViz canvas. Auto-save. Click the smiley face (": "— OntoViz 캔버스에서 엔티티, 관계, 상속 화살표를 드래그 앤 드롭하세요. 자동 저장됩니다. 스마일 아이콘을 클릭하세요(",
