    "— interactive sigma.js WebGL graph. Search, filter, detect clusters (Louvain / Label Propagation / Greedy Modularity), color-by-cluster, collapse into super-nodes": "— 인터랙티브 sigma.js WebGL 그래프입니다. 검색, 필터링, 클러스터 탐지(Louvain / Label Propagation / Greedy Modularity), 클러스터별 색상 지정, 슈퍼 노드로 축소가 가능합니다",
